create table if not exists public.client_intake_profiles (client_id uuid primary key references public.clients(id) on delete cascade, email text not null, address text, zone text, level text, phase text, frequency text not null, restrictions text, pain text, history text, equipment text, preferences text, primary_limiter text, current_recommendation text, pending text, onboarding_status text not null default 'expediente', created_by uuid not null references auth.users(id), updated_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint client_intake_email_check check (position('@' in email) > 1), constraint client_intake_status_check check (onboarding_status in ('expediente','preparacion','listo_para_invitar','invitado','activo'))); create unique index if not exists client_intake_profiles_email_unique on public.client_intake_profiles(lower(email)); create index if not exists client_intake_profiles_status_idx on public.client_intake_profiles(onboarding_status, updated_at desc); alter table public.client_intake_profiles enable row level security; drop policy if exists client_intake_read on public.client_intake_profiles; create policy client_intake_read on public.client_intake_profiles for select to authenticated using (client_id = (select public.iberfit_client_id()) or public.is_assigned_coach(client_id)); drop policy if exists client_intake_update on public.client_intake_profiles; create policy client_intake_update on public.client_intake_profiles for update to authenticated using (public.is_assigned_coach(client_id)) with check (public.is_assigned_coach(client_id));;
